public class SourceBlockIndenterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static final String MESSY = String.join("\n",
            "public class Demo {",
            "  private int x;",
            "",
            "        public void run() {",
            "if (x > 0) {",
            "            x--;",
            "} else {",
            "x++;",
            "}",
            "  }",
            "}");

    static final String TIDY = String.join("\n",
            "public class Demo {",
            "    private int x;",
            "",
            "    public void run() {",
            "        if (x > 0) {",
            "            x--;",
            "        } else {",
            "            x++;",
            "        }",
            "    }",
            "}");

    public static void main(String[] args) {
        check("a whole class is re-indented", TIDY, SourceBlockIndenter.indent(MESSY));
        check("re-indenting tidy source changes nothing", TIDY, SourceBlockIndenter.indent(TIDY));
        check("simple body", "class A {\n    int x;\n}",
                SourceBlockIndenter.indent("class A {\nint x;\n}"));
        check("a one-line block stays at depth 0", "class A { }",
                SourceBlockIndenter.indent("      class A { }"));
        check("blank lines stay empty", "a\n\nb", SourceBlockIndenter.indent("a\n     \nb"));
        check("a stray close brace never indents negatively", "}",
                SourceBlockIndenter.indent("}"));
        check("maxDepth of the class", 3, SourceBlockIndenter.maxDepth(MESSY));
        check("maxDepth with no braces", 0, SourceBlockIndenter.maxDepth("int x = 1;"));
        finish();
    }
}

