public class SourceBlockIndenter {

    public static String indent(String source) {
        String[] lines = source.split("\n", -1);
        StringBuilder out = new StringBuilder();
        int depth = 0;
        for (int i = 0; i < lines.length; i++) {
            String text = lines[i].trim();
            if (i > 0) {
                out.append("\n");
            }
            if (text.isEmpty()) {
                continue;
            }
            int level = depth;
            if (text.startsWith("}")) {
                level = depth - 1;
            }
            if (level < 0) {
                level = 0;
            }
            out.append("    ".repeat(level)).append(text);
            depth = depth + count(text, '{') - count(text, '}');
            if (depth < 0) {
                depth = 0;
            }
        }
        return out.toString();
    }

    public static int maxDepth(String source) {
        int max = 0;
        for (String line : indent(source).split("\n", -1)) {
            int spaces = 0;
            while (spaces < line.length() && line.charAt(spaces) == ' ') {
                spaces++;
            }
            if (!line.isEmpty() && spaces / 4 > max) {
                max = spaces / 4;
            }
        }
        return max;
    }

    private static int count(String text, char target) {
        int total = 0;
        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == target) {
                total++;
            }
        }
        return total;
    }
}
